#include <stdio.h>
/*
 * ex04：加权 CPI 与 CPU 时间
 * 公式：
 *   CPI = Σ(各类指令占比 × 该类 CPI)
 *   CPU时间 = 指令总数 IC × CPI / 主频
 * 这是 408 最常考的性能计算：给了指令混合比例就不能用「单条指令 CPI」算。
 */
int main(void) {
    /* 四类指令：ALU / load-store / 转移 / 其他 */
    const char *cls[4] = {"ALU", "load-store", "分支", "其他"};
    double ratio[4] = {0.45, 0.15, 0.25, 0.15};   /* 占比之和必须 = 1 */
    int    cpi[4]   = {1,     2,     3,     2};   /* 各类指令各自的 CPI */

    double cpi_avg = 0.0;
    printf("加权CPI = ");
    for (int i = 0; i < 4; i++) {
        cpi_avg += ratio[i] * cpi[i];             /* 按占比加权 */
        printf("%s%.2f*%d", i ? " + " : "", ratio[i], cpi[i]);   /* 逐项加权展开 */
    }
    printf(" = %.2f\n", cpi_avg);

    double ic = 1000.0;          /* 指令总数 */
    double freq = 2.0e9;         /* 主频 2GHz */
    double t = ic * cpi_avg / freq;   /* CPU 时间（秒）*/

    printf("指令总数 IC=%.0f\n", ic);
    printf("CPU时间 = IC*CPI/主频 = %.0f*%.2f/%.0e = %.3e 秒 (%.2f 微秒)\n",
           ic, cpi_avg, freq, t, t * 1e6);
    return 0;
}
